    button { padding: 10px 15px; font: inherit; color: white; background: #2459a6; border: 0; border-radius: 5px; cursor: pointer; }
    button:hover { background: #194783; }
    [role="alert"] { color: #a32121; margin: 12px 0; }
    .row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px; margin: 8px 0; background: white; border: 1px solid #dce2e9; border-radius: 6px; }
    .task-row { justify-content: flex-start; }
    .task-row input { flex: initial; }
    .filter { display: flex; align-items: center; gap: 10px; margin: 18px 0; }
    select { padding: 8px; font: inherit; }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        const projectResponse = await fetch(`/api/projects/${match[1]}`);
        const project = projectResponse.ok ? await projectResponse.json() : null;
        if (!project) {
          app.innerHTML = `<h1>Project not found</h1><button type="button" id="back">Projects</button>`;
          app.querySelector('#back').addEventListener('click', () => navigate('/'));
          return;
        }
        const tasksResponse = await fetch(`/api/projects/${match[1]}/tasks`);
        const tasks = await tasksResponse.json();
        app.innerHTML = `<button type="button" id="back">Projects</button><h1>${escapeHtml(project.name)}</h1>
          <form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"><button type="submit">Create task</button></form>
          <div id="message" role="alert" aria-live="polite"></div>
          <div class="filter"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div>
          <section id="task-list" aria-label="Tasks"></section>`;
        app.querySelector('#back').addEventListener('click', () => navigate('/'));
        const filter = app.querySelector('#task-filter');
        const paintTasks = () => {
          const visible = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === Boolean(task.completed));
          app.querySelector('#task-list').innerHTML = visible.map(task => `<div class="row task-row" data-testid="task-row"><input type="checkbox" id="task-${task.id}" aria-label="Complete ${escapeHtml(task.title)}" ${task.completed ? 'checked' : ''}><label for="task-${task.id}">${escapeHtml(task.title)}</label></div>`).join('');
          app.querySelectorAll('#task-list input[type="checkbox"]').forEach(box => box.addEventListener('change', async () => {
            const task = tasks.find(item => String(item.id) === box.id.slice(5));
            const response = await fetch(`/api/projects/${match[1]}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: box.checked }) });
            if (response.ok) { task.completed = box.checked ? 1 : 0; paintTasks(); }
          }));
        };
        filter.addEventListener('change', paintTasks);
        paintTasks();
        app.querySelector('#task-form').addEventListener('submit', async event => {
          event.preventDefault();
          const input = app.querySelector('#task-title');
          const title = input.value.trim();
          if (!title) { app.querySelector('#message').textContent = 'Task title is required'; input.focus(); return; }
          const result = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
          if (result.ok) { tasks.push(await result.json()); input.value = ''; app.querySelector('#message').textContent = ''; paintTasks(); }
        });
        return;
      }
      const response = await fetch('/api/projects');
      const projects = await response.json();
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text"><button type="submit">Create project</button></form>
        <div id="message" role="alert" aria-live="polite"></div>
        <section aria-label="Projects">${projects.map(project => `<div class="row" data-testid="project-row"><span>${escapeHtml(project.name)}</span><button type="button" data-open="${project.id}">Open project</button></div>`).join('')}</section>`;
      app.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const input = app.querySelector('#project-name');
        const name = input.value.trim();
        if (!name) { app.querySelector('#message').textContent = 'Project name is required'; input.focus(); return; }
        const result = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
        if (result.ok) render();
      });
      app.querySelectorAll('[data-open]').forEach(button => button.addEventListener('click', () => navigate(`/projects/${button.dataset.open}`)));
    }
    function navigate(path) { history.pushState({}, '', path); render(); }
    addEventListener('popstate', render);
    render();
  </script>
</body>
</html>
